function animate(list){const prep=list.filter(o=>o.kind==='path'&&o.pts&&o.pts.length>1);prep.forEach(o=>{o.cum=[0];for(let i=1;i<o.pts.length;i++)o.cum.push(o.cum[i-1]+Math.hypot(o.pts[i][0]-o.pts[i-1][0],o.pts[i][1]-o.pts[i-1][1]));o.L=o.cum[o.cum.length-1]});
let last=0;function f(t){requestAnimationFrame(f);if(document.hidden||t-last<40)return;last=t;const s=t/1000;
list.forEach(o=>{if(o.kind==='bob'){const x=o.base[0]+Math.sin(s/o.per*6.283+o.ph)*o.amp,y=o.base[1]+Math.sin(s*1.3+o.ph)*1.4,r=Math.sin(s*1.1+o.ph)*2.5;o.g.setAttribute('transform',`translate(${x.toFixed(1)},${y.toFixed(1)}) rotate(${r.toFixed(1)})`)}
else if(o.kind==='path'&&o.L){const d=(s*o.speed+o.off)%(2*o.L),fw=d<o.L,p=fw?d:2*o.L-d;let lo=0,hi=o.cum.length-1;while(hi-lo>1){const mid=(lo+hi)>>1;if(o.cum[mid]<=p)lo=mid;else hi=mid}const a=o.pts[lo],b=o.pts[hi],k=(p-o.cum[lo])/((o.cum[hi]-o.cum[lo])||1),x=a[0]+(b[0]-a[0])*k,y=a[1]+(b[1]-a[1])*k;let th=Math.atan2(b[1]-a[1],b[0]-a[0])*180/Math.PI;if(!fw)th+=180;let tr;if(o.sym){th=((th+180)%360+360)%360-180;if(th>90)th-=180;if(th<-90)th+=180;tr=`rotate(${th.toFixed(1)})`}else{const c=Math.cos(th*Math.PI/180);tr=c>=0?`rotate(${th.toFixed(1)})`:`rotate(${(th-180).toFixed(1)}) scale(-1,1)`}o.g.setAttribute('transform',`translate(${x.toFixed(1)},${y.toFixed(1)}) ${tr}`)}
else if(o.kind==='drift'){const x=-1700+((o.base[0]+1700+s*o.speed)%4400);o.g.setAttribute('transform',`translate(${x.toFixed(1)},${o.base[1]}) scale(${o.s})`)}
else if(o.kind==='fly'){const k=(s%o.dur)/o.dur,x=o.from[0]+(o.to[0]-o.from[0])*k,y=o.from[1]+(o.to[1]-o.from[1])*k,th=Math.atan2(o.to[1]-o.from[1],o.to[0]-o.from[0])*180/Math.PI,sc=.8+Math.min(k*6,1)*.5;o.g.setAttribute('transform',`translate(${x.toFixed(1)},${y.toFixed(1)}) rotate(${th.toFixed(1)}) scale(${sc.toFixed(2)})`)}})}requestAnimationFrame(f)}
window.HMap={animate,build,decorate,shermerCloud,cards,glyph,mascot,shoreX,isWater,el,HOME:[492,1250]};
